package com.gameaggregator.billingservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;@Entity @Table(name="invoice_items") public class InvoiceItem{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID invoiceId;@Column(nullable=false)public String description;@Column(nullable=false)public long quantity;@Column(nullable=false,precision=19,scale=6)public BigDecimal unitPrice;@Column(nullable=false,precision=19,scale=6)public BigDecimal amount;protected InvoiceItem(){}public InvoiceItem(UUID i,String d,long q,BigDecimal p){invoiceId=i;description=d;quantity=q;unitPrice=p;amount=p.multiply(BigDecimal.valueOf(q));}}